const METHODS_DP = [{"id": "3.1.1.1", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S1 - Calculus of exponential functions", "code": "3.1.1.1", "descriptor": "Estimate the limit of (aʰ−1)/h as h→0, using technology, for various values of a>0.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.1.2", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S1 - Calculus of exponential functions", "code": "3.1.1.2", "descriptor": "Recognise that e is the unique number a for which the above limit is 1.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For a general base a, the limit of (aʰ−1)/h as h→0 gives the gradient of y=aˣ at x=0, and this gradient value changes depending on which base a is chosen.", "Euler's number e (≈2.71828) is defined as the specific base for which this limit equals exactly 1 — i.e. the unique value of a for which y=aˣ has gradient exactly 1 at x=0.", "This special property is precisely why e^x is its own derivative (d/dx eˣ = eˣ), making e the natural base for calculus, in contrast to other bases which pick up an extra constant factor (ln a) when differentiated."]}, {"id": "3.1.1.3", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S1 - Calculus of exponential functions", "code": "3.1.1.3", "descriptor": "Recognise and determine the qualitative features of the graph of y=eˣ, including asymptote and intercept.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The graph of y=eˣ has a horizontal asymptote at y=0 as x→−∞ (the curve approaches but never reaches the x-axis), and increases without bound as x→+∞.", "It has a y-intercept at (0,1), since e⁰=1, and has no x-intercept, since eˣ>0 for all real x.", "The function is always increasing and always concave up (its gradient eˣ is itself always positive and always increasing)."]}, {"id": "3.1.1.4", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S1 - Calculus of exponential functions", "code": "3.1.1.4", "descriptor": "Use the rules d/dx eˣ = eˣ and d/dx e^f(x) = f'(x)e^f(x).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.1", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S2 - Calculus of logarithmic functions", "code": "3.1.2.1", "descriptor": "Recognise and determine the qualitative features of the graph of y=ln(x)=logₑ(x), including asymptote and intercept.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The graph of y=ln(x) has a vertical asymptote at x=0 (the curve plunges toward −∞ as x→0⁺) and is only defined for x>0.", "It has an x-intercept at (1,0), since ln(1)=0, and has no y-intercept (the function is undefined at x=0).", "The function is always increasing but always concave down, increasing more and more slowly as x grows larger — the mirror image (reflection in y=x) of the graph of y=eˣ."]}, {"id": "3.1.2.2", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S2 - Calculus of logarithmic functions", "code": "3.1.2.2", "descriptor": "Recognise and use the inverse relationship of the functions y=eˣ and y=ln(x).", "graphical": false, "needsExplanation": true, "modelAnswer": ["y=eˣ and y=ln(x) are inverse functions of each other: applying one after the other returns the original input, i.e. ln(eˣ)=x and e^(ln x)=x (for x>0).", "Because they are inverses, their graphs are reflections of one another in the line y=x, which is why one has a horizontal asymptote (y=0) while the other has a vertical asymptote (x=0), and their intercepts (0,1) and (1,0) are also mirror images.", "This inverse relationship is what allows exponential and logarithmic equations to be solved by converting between the two forms — e.g. taking ln of both sides of an equation involving eˣ, or exponentiating both sides of an equation involving ln(x)."]}, {"id": "3.1.2.3", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S2 - Calculus of logarithmic functions", "code": "3.1.2.3", "descriptor": "Solve equations involving exponential and logarithmic functions with base e, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.4", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S2 - Calculus of logarithmic functions", "code": "3.1.2.4", "descriptor": "Use the rules d/dx ln(x) = 1/x and d/dx ln(f(x)) = f'(x)/f(x).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.1.2.5", "unit": 3, "topic": "T1 - Differentiation of exponential and logarithmic functions", "subtopic": "S2 - Calculus of logarithmic functions", "code": "3.1.2.5", "descriptor": "Model and solve problems that involve derivatives of exponential and logarithmic functions, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.1", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S1 - Calculus of trigonometric functions", "code": "3.2.1.1", "descriptor": "Use the rules d/dx sin(x)=cos(x) and d/dx sin(f(x))=f'(x)cos(f(x)).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.2", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S1 - Calculus of trigonometric functions", "code": "3.2.1.2", "descriptor": "Use the rules d/dx cos(x)=−sin(x) and d/dx cos(f(x))=−f'(x)sin(f(x)).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.1.3", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S1 - Calculus of trigonometric functions", "code": "3.2.1.3", "descriptor": "Model and solve problems that involve derivatives of trigonometric functions, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.1", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S2 - Differentiation rules", "code": "3.2.2.1", "descriptor": "Use the chain rule to determine the derivative of composite functions involving exponential, logarithmic and trigonometric functions, expressing derivatives in simplest and factorised form.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.2", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S2 - Differentiation rules", "code": "3.2.2.2", "descriptor": "Use the product rule to determine the derivative of exponential, logarithmic and trigonometric functions, expressing derivatives in simplest and factorised form.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.3", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S2 - Differentiation rules", "code": "3.2.2.3", "descriptor": "Use the quotient rule to determine the derivative of exponential, logarithmic and trigonometric functions, expressing derivatives in simplest and factorised form.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.2.2.4", "unit": 3, "topic": "T2 - Differentiation of trigonometric functions and differentiation rules", "subtopic": "S2 - Differentiation rules", "code": "3.2.2.4", "descriptor": "Solve problems that involve combinations of the chain rule, product rule and quotient rule to differentiate exponential, logarithmic and trigonometric functions.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.3.1.1", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.1", "descriptor": "Understand the concept of the second derivative as the rate of change of the first derivative function.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The second derivative, f''(x) (or d²y/dx²), measures how the gradient function f'(x) itself is changing as x changes — it is the derivative of the derivative.", "Just as f'(x) tells you the rate of change of f(x), f''(x) tells you the rate of change of that rate of change — i.e. whether the gradient is getting steeper or shallower as x increases.", "This makes the second derivative a natural tool for describing curvature: a large positive f''(x) means the gradient is increasing rapidly, while a large negative f''(x) means it is decreasing rapidly."]}, {"id": "3.3.1.2", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.2", "descriptor": "Recognise acceleration as the second derivative of displacement position with respect to time.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Velocity is the first derivative of displacement with respect to time (v=dx/dt), describing how position changes over time.", "Acceleration is the derivative of velocity with respect to time, which is equivalently the second derivative of displacement with respect to time: a=dv/dt=d²x/dt².", "This chain (displacement → velocity → acceleration, via successive differentiation) is a direct physical application of the general concept of the second derivative as a 'rate of change of a rate of change'."]}, {"id": "3.3.1.3", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.3", "descriptor": "Understand the concepts of concavity and points of inflection and their relationship with the second derivative.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A curve is concave up on an interval where f''(x)>0 (the gradient is increasing, and the curve bends upward like a cup), and concave down where f''(x)<0 (the gradient is decreasing, curving downward like a cap).", "A point of inflection is a point where the curve changes from concave up to concave down (or vice versa) — the concavity switches sign.", "At a point of inflection, f''(x)=0 (or is undefined), though the converse isn't automatically true: f''(x)=0 alone doesn't guarantee an inflection point unless concavity actually changes sign either side of that point."]}, {"id": "3.3.1.4", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.4", "descriptor": "Understand and use the second derivative test for finding local maxima and minima.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The second derivative test uses the sign of f''(x) at a stationary point (where f'(x)=0) to classify it: if f''(x)>0 there, the curve is concave up at that point, indicating a local minimum; if f''(x)<0, the curve is concave down, indicating a local maximum.", "If f''(x)=0 at the stationary point, the test is inconclusive — the point could be a local max, local min, or a stationary point of inflection, and a different method (e.g. checking the sign of f'(x) either side) is needed instead.", "This test offers a faster alternative to the first derivative (sign-change) test in cases where f''(x) is straightforward to evaluate at the stationary point."]}, {"id": "3.3.1.5", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.5", "descriptor": "Sketch the graph of a function using first and second derivatives to locate stationary points and points of inflection.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.3.1.6", "unit": 3, "topic": "T3 - Further applications of differentiation", "subtopic": "S1 - The second derivative and applications of differentiation", "code": "3.3.1.6", "descriptor": "Model and solve optimisation problems from a wide variety of fields using first and second derivatives, where the function to be optimised is either given or to be developed.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.1", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.1", "descriptor": "Recognise anti-differentiation as the reverse of differentiation.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Anti-differentiation (integration) is the reverse process of differentiation: given a function's derivative, it finds a function that could have produced that derivative.", "Because differentiation of a constant is always zero, reversing it introduces an unknown constant of integration, c — so anti-differentiation produces a whole family of functions (differing only by a constant), not one single function.", "This inverse relationship means anti-differentiating and then differentiating (or vice versa, up to the constant) returns you to your starting function, similarly to how squaring and square-rooting undo each other."]}, {"id": "3.4.1.2", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.2", "descriptor": "Use the notation ∫f(x)dx for anti-derivatives or indefinite integrals.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.3", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.3", "descriptor": "Use the formula ∫xⁿdx = x^(n+1)/(n+1) + c for n≠−1.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.4", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.4", "descriptor": "Use the formula ∫eˣdx = eˣ + c.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.5", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.5", "descriptor": "Use the formula ∫1/x dx = ln(x) + c, for x>0.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.6", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.6", "descriptor": "Use the formulas ∫sin(x)dx=−cos(x)+c and ∫cos(x)dx=sin(x)+c.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.7", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.7", "descriptor": "Understand and use the formulas ∫(f(x)+g(x))dx=∫f(x)dx+∫g(x)dx and ∫kf(x)dx=k∫f(x)dx.", "graphical": false, "needsExplanation": true, "modelAnswer": ["These two properties (linearity of integration) mirror the equivalent linearity properties of differentiation: the integral of a sum is the sum of the integrals, and a constant multiple can be pulled outside the integral sign.", "This means a complicated-looking function can often be broken into simpler additive pieces (or have constant factors separated out), each integrated individually, then recombined — without needing more advanced integration techniques.", "These rules only combine terms added or subtracted (or scaled by a constant); they do NOT apply to integrating a product or quotient of two functions, which generally require different techniques altogether."]}, {"id": "3.4.1.8", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.8", "descriptor": "Determine indefinite integrals of the form ∫f(ax+b)dx.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.9", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.9", "descriptor": "Determine f(x) given f'(x) and an initial condition f(a)=b.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.10", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.10", "descriptor": "Determine displacement given velocity and the initial value of displacement.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.11", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.11", "descriptor": "Determine displacement given acceleration and initial values of displacement and velocity.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.4.1.12", "unit": 3, "topic": "T4 - Introduction to integration", "subtopic": "S1 - Anti-differentiation", "code": "3.4.1.12", "descriptor": "Model and solve problems that involve indefinite integrals, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.1.1", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.1", "descriptor": "Understand the concepts of a discrete random variable and its associated probability function, and its use in modelling data.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A discrete random variable is a variable whose possible outcomes form a countable set of distinct values (e.g. 0, 1, 2, 3…), as opposed to a continuous range.", "Its probability function assigns a probability to each possible outcome, with all these probabilities summing to exactly 1 across the whole set of outcomes.", "Discrete random variables are used to model real-world processes with distinct, separate possible outcomes — e.g. the number of heads in several coin tosses, or the number of defective items in a batch."]}, {"id": "3.5.1.2", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.2", "descriptor": "Use relative frequencies obtained from data to determine point estimates of probabilities associated with a discrete random variable.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.1.3", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.3", "descriptor": "Recognise uniform discrete random variables and use them to model random phenomena with equally likely outcomes.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A uniform discrete random variable assigns exactly equal probability to each of its possible outcomes — e.g. a fair six-sided die, where each face has probability 1/6.", "This makes it a natural model for genuinely equally-likely processes, where no particular outcome is more or less likely than any other.", "Because every outcome has the same probability, the probability function is simply 1/(number of outcomes) for every possible value the variable can take."]}, {"id": "3.5.1.4", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.4", "descriptor": "Recognise non-uniform discrete random variables and use them to model random phenomena.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A non-uniform discrete random variable assigns different probabilities to different outcomes, rather than spreading probability evenly.", "This is the more general/common case, needed to model most real-world discrete processes, where certain outcomes genuinely occur more frequently than others (e.g. the number of customers arriving at a shop in an hour).", "The specific probability function for a non-uniform variable must be determined from the underlying process or from data, rather than simply dividing 1 by the number of outcomes."]}, {"id": "3.5.1.5", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.5", "descriptor": "Determine and use the mean (expected value) of a discrete random variable as a measurement of centre, E(X)=μ=Σpᵢxᵢ where pᵢ is the probability of outcome xᵢ occurring.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.1.6", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.6", "descriptor": "Determine and use the variance of a discrete random variable as a measure of spread, Var(X)=Σpᵢ(xᵢ−μ)² where pᵢ is the probability of outcome xᵢ occurring, μ is the mean.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.1.7", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.7", "descriptor": "Determine and use the standard deviation of a discrete random variable, √Var(X), as a measure of spread.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.1.8", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S1 - General discrete random variables", "code": "3.5.1.8", "descriptor": "Model and solve problems that involve discrete random variables and associated probabilities, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.2.1", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S2 - Bernoulli distributions", "code": "3.5.2.1", "descriptor": "Use a Bernoulli random variable as a model for two-outcome situations.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A Bernoulli random variable takes only two possible values, conventionally labelled 1 ('success') and 0 ('failure'), representing a single trial with exactly two possible outcomes.", "It is the simplest possible discrete random variable, used to model any single yes/no, success/failure, or true/false situation (e.g. a single coin toss, or whether a single item is defective).", "It underpins more complex distributions (like the binomial distribution), which model repeated, independent Bernoulli trials."]}, {"id": "3.5.2.2", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S2 - Bernoulli distributions", "code": "3.5.2.2", "descriptor": "Identify contexts suitable for modelling by Bernoulli random variables.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A context suits Bernoulli modelling when it involves a single trial with exactly two possible mutually exclusive outcomes, one of which is designated 'success'.", "Examples include: a single product passing or failing quality control, a single free throw being made or missed, or a single survey respondent answering yes or no to a question.", "The key requirement is that there is only ONE trial being considered (not several repeated ones) — repeated independent Bernoulli trials are instead modelled using the binomial distribution."]}, {"id": "3.5.2.3", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S2 - Bernoulli distributions", "code": "3.5.2.3", "descriptor": "Recognise and determine the mean p and variance p(1−p) of the Bernoulli distribution with parameter p.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For a Bernoulli random variable with probability of success p, the mean (expected value) is simply p itself — since E(X) = (1×p) + (0×(1−p)) = p.", "The variance is p(1−p), which can be derived directly from the general variance formula Var(X)=Σpᵢ(xᵢ−μ)² applied to the two possible outcomes.", "The variance p(1−p) is maximised when p=0.5 (maximum uncertainty about the outcome) and approaches 0 as p approaches 0 or 1 (the outcome becomes near-certain)."]}, {"id": "3.5.2.4", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S2 - Bernoulli distributions", "code": "3.5.2.4", "descriptor": "Model and solve problems that involve Bernoulli random variables and associated probabilities, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.3.1", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.1", "descriptor": "Understand the concepts of Bernoulli trials and the concept of a binomial random variable as the number of 'successes', r, in n independent Bernoulli trials, with the same probability of success p in each trial.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A Bernoulli trial is a single repetition of a two-outcome (success/failure) experiment, with a fixed probability of success p that stays the same on every repetition.", "A binomial random variable counts the total number of successes, r, across n such independent, identical Bernoulli trials.", "For the binomial model to apply, the trials must be independent of one another (the outcome of one doesn't affect the others) and each must have the exact same probability of success p."]}, {"id": "3.5.3.2", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.2", "descriptor": "Identify contexts suitable for modelling by binomial random variables.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A context suits binomial modelling when there are a fixed number of independent, identical trials, each with only two possible outcomes and a constant probability of success across all trials.", "Examples include: the number of heads in 20 coin tosses, the number of defective items in a fixed sample size from a large batch (approximately, if sampling without replacement from a very large population), or the number of correct guesses on a fixed number of independent multiple-choice questions.", "If the probability of success changes between trials, or the trials are not independent, or there isn't a clearly fixed number of trials, the binomial model does not directly apply."]}, {"id": "3.5.3.3", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.3", "descriptor": "Determine and use the probabilities P(X=r) = C(n,r) pʳ(1−p)ⁿ⁻ʳ associated with the binomial distribution with parameters n and p.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.3.4", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.4", "descriptor": "Calculate the mean np and variance np(1−p) of a binomial distribution using technology and algebraic methods.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.3.5", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.5", "descriptor": "Use the language of probability, including at most, at least, no more than, no less than, inclusive and between.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "3.5.3.6", "unit": 3, "topic": "T5 - Discrete random variables", "subtopic": "S3 - Binomial distributions", "code": "3.5.3.6", "descriptor": "Model and solve problems that involve binomial distributions and associated probabilities with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.1", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S1 - Fundamental theorem of calculus and definite integrals", "code": "4.1.1.1", "descriptor": "Use sums of the form Σᵢ f(xᵢ)δxᵢ to estimate the area under the curve y=f(x).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.1.2", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S1 - Fundamental theorem of calculus and definite integrals", "code": "4.1.1.2", "descriptor": "Recognise the definite integral ∫[a,b] f(x)dx as a limit of sums of the form Σᵢ f(xᵢ)δxᵢ.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The sum Σᵢ f(xᵢ)δxᵢ approximates the area under a curve by adding up the areas of many thin rectangles, each of width δxᵢ and height f(xᵢ).", "As the number of rectangles increases (and each width δxᵢ shrinks toward zero), this sum becomes an increasingly accurate approximation of the true area under the curve.", "The definite integral ∫[a,b] f(x)dx is defined as the exact limiting value this sum approaches as the rectangle width shrinks to zero and the number of rectangles grows to infinity — giving integration a concrete geometric meaning as 'area under a curve', built from an infinite sum of infinitesimally thin slices."]}, {"id": "4.1.1.3", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S1 - Fundamental theorem of calculus and definite integrals", "code": "4.1.1.3", "descriptor": "Understand the fundamental theorem of calculus, ∫[a,b] f(x)dx = F(b)−F(a), and use it to calculate definite integrals.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The fundamental theorem of calculus states that if F(x) is any antiderivative of f(x) (i.e. F'(x)=f(x)), then the definite integral of f(x) from a to b equals F(b)−F(a).", "This is a profound result because it connects two seemingly different ideas: differentiation (the gradient of a curve) and definite integration (the area under a curve) — showing they are inverse processes of one another.", "Practically, this means definite integrals (areas) can be calculated directly via antidifferentiation and substitution of the bounds, without ever needing to compute the limit of a sum of rectangles directly."]}, {"id": "4.1.1.4", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S1 - Fundamental theorem of calculus and definite integrals", "code": "4.1.1.4", "descriptor": "Use the definite integral ∫[a,b] f(x)dx to determine the area under the curve y=f(x) between x=a and x=b if f(x)>0 over this interval.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.1", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S2 - Applications of integration", "code": "4.1.2.1", "descriptor": "Calculate the area enclosed by a curve and the x-axis over a given domain, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.2", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S2 - Applications of integration", "code": "4.1.2.2", "descriptor": "Calculate the area between curves, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.3", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S2 - Applications of integration", "code": "4.1.2.3", "descriptor": "Use the trapezoidal rule to approximate an area and the value of a definite integral, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.4", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S2 - Applications of integration", "code": "4.1.2.4", "descriptor": "Calculate total change by integrating instantaneous or marginal rates of change, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.1.2.5", "unit": 4, "topic": "T1 - Further integration", "subtopic": "S2 - Applications of integration", "code": "4.1.2.5", "descriptor": "Model and solve problems that involve definite integrals, including motion problems, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.1", "unit": 4, "topic": "T2 - Trigonometry", "subtopic": "S1 - Cosine and sine rules", "code": "4.2.1.1", "descriptor": "Use the sine rule (ambiguous case is required), a/sin(A) = b/sin(B) = c/sin(C), where a, b and c are the side lengths of the triangle and A, B and C are the corresponding opposite angles.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.2", "unit": 4, "topic": "T2 - Trigonometry", "subtopic": "S1 - Cosine and sine rules", "code": "4.2.1.2", "descriptor": "Use the cosine rule, c² = a²+b²−2ab cos(C).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.3", "unit": 4, "topic": "T2 - Trigonometry", "subtopic": "S1 - Cosine and sine rules", "code": "4.2.1.3", "descriptor": "Use the formula area = ½bc sin(A) to calculate the area of a triangle.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.2.1.4", "unit": 4, "topic": "T2 - Trigonometry", "subtopic": "S1 - Cosine and sine rules", "code": "4.2.1.4", "descriptor": "Model and solve problems that involve the sine rule, cosine rule and the area formula in two- and three-dimensional contexts (including bearings, directions and angles of elevation and depression), with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.1.1", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S1 - General continuous random variables", "code": "4.3.1.1", "descriptor": "Use relative frequencies and histograms obtained from data to estimate probabilities associated with a continuous random variable.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.1.2", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S1 - General continuous random variables", "code": "4.3.1.2", "descriptor": "Understand the concepts of a probability density function, cumulative distribution function, and probabilities associated with a continuous random variable given by integrals; examine simple types of continuous random variables and use them in appropriate contexts.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A probability density function (PDF) describes the relative likelihood of a continuous random variable taking values near a given point; unlike discrete probabilities, the PDF's value at a single point is not itself a probability (since a continuous variable has zero probability of taking any exact single value).", "Probabilities for a continuous random variable correspond to the AREA under the PDF curve over an interval, calculated by integrating the PDF between the interval's endpoints.", "The cumulative distribution function (CDF) gives the probability that the random variable is less than or equal to a given value, and is found by integrating the PDF from −∞ (or the lower limit of the variable's range) up to that value — the CDF is therefore the running total (accumulated area) under the PDF."]}, {"id": "4.3.1.3", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S1 - General continuous random variables", "code": "4.3.1.3", "descriptor": "Calculate the expected value, E(X)=μ=∫xp(x)dx, of a continuous random variable where p(x) is the probability density function.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.1.4", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S1 - General continuous random variables", "code": "4.3.1.4", "descriptor": "Calculate the variance, Var(X)=σ²=∫(x−μ)²p(x)dx, and standard deviation σ, of a continuous random variable.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.1.5", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S1 - General continuous random variables", "code": "4.3.1.5", "descriptor": "Understand standardised normal variables (z-values, z-scores) and use these to compare samples.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A z-score (or standardised value) expresses how many standard deviations a particular value lies above or below the mean of its distribution: z=(x−μ)/σ.", "Standardising in this way converts values from any normal distribution onto a common scale (the standard normal distribution, mean 0 and standard deviation 1), regardless of the original distribution's own mean and standard deviation.", "This common scale allows values or samples from different normal distributions (with different means/standard deviations) to be meaningfully compared — e.g. determining which of two students performed relatively better on two different tests with different score distributions."]}, {"id": "4.3.2.1", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S2 - Normal distributions", "code": "4.3.2.1", "descriptor": "Identify contexts, e.g. naturally occurring variations, that are suitable for modelling by normal random variables.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The normal distribution suits variables that cluster symmetrically around a central average value, with values becoming progressively less likely the further they are from that average in either direction.", "Many naturally occurring measurements follow this pattern closely, such as human heights, measurement errors, or biological characteristics within a population — arising from the combined, largely independent effect of many small random factors.", "The normal distribution is generally NOT suitable for modelling variables that are heavily skewed, bounded to only positive values with a mean close to that boundary, or that have distinctly non-bell-shaped patterns (e.g. multiple peaks)."]}, {"id": "4.3.2.2", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S2 - Normal distributions", "code": "4.3.2.2", "descriptor": "Recognise features of the graph of the probability density function of the normal distribution with mean μ and standard deviation σ and the use of the standard normal distribution.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The normal distribution's PDF is a symmetric, bell-shaped curve, centred at (and with its peak at) the mean μ, with the spread of the curve controlled by the standard deviation σ (a larger σ gives a wider, flatter curve).", "The curve is symmetric about x=μ, approaches (but never quite reaches) zero as x moves far from μ in either direction, and the total area under the entire curve equals exactly 1.", "The standard normal distribution is the special case with μ=0 and σ=1; any normal distribution can be converted to this standard form via the z-score transformation, allowing a single reference distribution to be used for calculating probabilities for any normal distribution."]}, {"id": "4.3.2.3", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S2 - Normal distributions", "code": "4.3.2.3", "descriptor": "Recognise and use the link between the normal distribution and the notation X∼N(μ,σ²).", "graphical": false, "needsExplanation": true, "modelAnswer": ["The notation X∼N(μ,σ²) is shorthand stating that the random variable X follows a normal distribution with mean μ and variance σ² (note: variance, not standard deviation, is the second parameter in this notation).", "This compact notation immediately specifies the full shape, centre and spread of the distribution being used, without needing to write out the full PDF formula each time.", "Recognising this notation allows quick identification of a variable's mean and standard deviation (μ and √σ²) for use in further calculations, such as finding z-scores or probabilities."]}, {"id": "4.3.2.4", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S2 - Normal distributions", "code": "4.3.2.4", "descriptor": "Calculate probabilities and quantiles associated with a given normal distribution, using technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.3.2.5", "unit": 4, "topic": "T3 - Continuous random variables and the normal distribution", "subtopic": "S2 - Normal distributions", "code": "4.3.2.5", "descriptor": "Model and solve problems that involve normal distributions, with and without technology (distribution tables are not required).", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.4.1.1", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S1 - Random sampling", "code": "4.4.1.1", "descriptor": "Understand the concept of a random sample.", "graphical": false, "needsExplanation": true, "modelAnswer": ["A random sample is a subset of a population selected in such a way that every member of the population has a known, non-zero (often equal) chance of being included.", "Randomness in the selection process is what allows a sample to be considered representative of the wider population, supporting valid statistical inference from the sample back to that population.", "Without genuine randomness, a sample can systematically over- or under-represent certain groups within the population, undermining the validity of any conclusions drawn from it."]}, {"id": "4.4.1.2", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S1 - Random sampling", "code": "4.4.1.2", "descriptor": "Understand sources of bias in samples, and procedures to ensure randomness.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Sampling bias occurs when the method of selecting a sample systematically favours certain members of the population over others, so the sample no longer accurately reflects the population as a whole.", "Common sources of bias include convenience sampling (choosing whoever is easiest to reach), self-selection bias (only those who choose to respond are included), and undercoverage (some parts of the population have no chance of being selected at all).", "Procedures to help ensure genuine randomness include using a formal random number generator or lottery method to select participants, ensuring every member of the population is included in the selection frame, and avoiding any selection method that relies on convenience or self-selection."]}, {"id": "4.4.1.3", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S1 - Random sampling", "code": "4.4.1.3", "descriptor": "Identify and use procedures to ensure randomness.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.4.1.4", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S1 - Random sampling", "code": "4.4.1.4", "descriptor": "Recognise and use graphical displays of real and simulated data of random samples from various types of distributions, including uniform, Bernoulli, binomial and normal.", "graphical": true, "needsExplanation": false, "modelAnswer": null}, {"id": "4.4.2.1", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S2 - Sample proportions", "code": "4.4.2.1", "descriptor": "Understand the concept of the sample proportion p̂ as a random variable whose value varies between samples, and the formulas for the mean p and standard deviation √(p(1−p)/n) of the sample proportion p̂, where n is the sample size.", "graphical": false, "needsExplanation": true, "modelAnswer": ["The sample proportion p̂ is the proportion of 'successes' observed in a particular random sample; because different random samples generally contain different numbers of successes, p̂ itself varies from sample to sample and is treated as a random variable.", "The mean of this sampling distribution of p̂ is p, the true (unknown) population proportion — meaning p̂ is, on average across many samples, centred correctly on the true value.", "The standard deviation of p̂ is √(p(1−p)/n), which decreases as the sample size n increases — larger samples produce sample proportions that cluster more tightly around the true population proportion p."]}, {"id": "4.4.2.2", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S2 - Sample proportions", "code": "4.4.2.2", "descriptor": "Recognise and use the approximate normality of the distribution of p̂ for large samples.", "graphical": false, "needsExplanation": true, "modelAnswer": ["For sufficiently large sample sizes, the sampling distribution of p̂ becomes approximately bell-shaped (normal), even though p̂ is fundamentally derived from an underlying binomial (discrete) process.", "This approximate normality is what allows normal-distribution-based methods (z-scores, confidence intervals) to be applied to sample proportions, despite proportions technically coming from a discrete binomial count.", "The quality of this normal approximation depends on both the sample size n and how close p is to 0 or 1 — the approximation is generally poorer for small n or for p values very close to the extremes."]}, {"id": "4.4.2.3", "unit": 4, "topic": "T4 - Sampling and proportions", "subtopic": "S2 - Sample proportions", "code": "4.4.2.3", "descriptor": "Use repeated random sampling data, for a variety of values of p and a range of sample sizes, to examine the distribution of p̂ and the approximate standard normality of (p̂−p)/√(p̂(1−p̂)/n), where the closeness of the approximation depends on both n and p.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Simulating many repeated random samples for a given p and sample size n, then calculating p̂ for each, shows the resulting sample proportions cluster around the true p with a spread matching the theoretical standard deviation √(p(1−p)/n).", "Standardising these simulated p̂ values using (p̂−p)/√(p̂(1−p̂)/n) and examining their distribution shows it becomes increasingly close to a standard normal distribution as the sample size n grows.", "Comparing this simulation across different values of p and n reveals that the normal approximation is better (closer to standard normal) for larger n, and better for p closer to 0.5 than for p very close to 0 or 1 at a given n — both n and p jointly determine how good the approximation is."]}, {"id": "4.5.1.1", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.1", "descriptor": "Understand the concept of an interval estimate for a parameter associated with a random variable.", "graphical": false, "needsExplanation": true, "modelAnswer": ["An interval estimate provides a range of plausible values for an unknown population parameter (such as p, the population proportion), rather than relying on a single point estimate value.", "It is calculated from sample data and reflects the inherent uncertainty in using a limited sample to draw conclusions about an entire population.", "A wider interval reflects greater uncertainty (e.g. from a smaller sample or a higher desired confidence level), while a narrower interval reflects a more precise estimate of the parameter's likely value."]}, {"id": "4.5.1.2", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.2", "descriptor": "Understand and use the approximate confidence interval, (p̂−z√(p̂(1−p̂)/n), p̂+z√(p̂(1−p̂)/n)), as an interval estimate for p, the population proportion, where z is the appropriate quantile for the standard normal distribution.", "graphical": false, "needsExplanation": true, "modelAnswer": ["This confidence interval is centred on the sample proportion p̂, extending equally in each direction by a margin z√(p̂(1−p̂)/n).", "z is the quantile from the standard normal distribution corresponding to the desired confidence level (e.g. z≈1.96 for a 95% confidence interval).", "The interval relies on the approximate normality of the sampling distribution of p̂ for large samples — values within roughly z standard deviations of the observed p̂ are considered plausible values for the true population proportion p."]}, {"id": "4.5.1.3", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.3", "descriptor": "Understand and use the approximate margin of error, z√(p̂(1−p̂)/n).", "graphical": false, "needsExplanation": true, "modelAnswer": ["The margin of error is the amount added and subtracted from the sample proportion p̂ to form the upper and lower bounds of the confidence interval.", "It combines the chosen confidence level (via z), the estimated variability in the sample proportion (via p̂(1−p̂)), and the sample size (via n in the denominator) into a single measure of the interval's half-width.", "A smaller margin of error corresponds to a more precise (narrower) interval estimate of the true population proportion."]}, {"id": "4.5.1.4", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.4", "descriptor": "Understand and use the relationship between margin of error, level of confidence and sample size.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Increasing the level of confidence (e.g. from 90% to 99%) increases z, which increases the margin of error and produces a wider interval — greater confidence requires a bigger range to be more sure of capturing the true p.", "Increasing the sample size n decreases the margin of error (since the √n term in the denominator grows), producing a narrower interval for the same level of confidence — more data gives a more precise estimate.", "There is a direct trade-off for a fixed sample size: choosing a more confident (wider) interval always comes at the cost of reduced precision, and vice versa."]}, {"id": "4.5.1.5", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.5", "descriptor": "Understand that there are variations in confidence intervals between samples and that most, but not all, confidence intervals contain p.", "graphical": false, "needsExplanation": true, "modelAnswer": ["Each different random sample produces a different p̂, and therefore a different confidence interval — the calculated interval itself is a random quantity that varies from sample to sample, even though the true p does not change.", "A 95% confidence level means that if the sampling and interval-construction process were repeated many times, approximately 95% of the resulting intervals would contain the true population proportion p.", "This does not mean there is a 95% probability that p lies within any one specific calculated interval — p is a fixed (though unknown) value, so a particular interval either does or does not contain it; the 95% describes the long-run success rate of the method across many repeated samples, not the chance for any single interval."]}, {"id": "4.5.1.6", "unit": 4, "topic": "T5 - Interval estimates for proportions", "subtopic": "S1 - Confidence intervals for proportions", "code": "4.5.1.6", "descriptor": "Model and solve problems that involve interval estimates for proportions, with and without technology.", "graphical": true, "needsExplanation": false, "modelAnswer": null}];
